const crypto = require('crypto');
const binary = $input.first().binary;
const key = Object.keys(binary)[0];
const buf = Buffer.from(binary[key].data, 'base64');
const hash = crypto.createHash('sha256').update(buf).digest('hex');
return [{ json: { ...items[0].json, file_hash: hash, file_name: binary[key].fileName || 'invoice.pdf' }, binary }];

// Rename Gmail attachment binary field from 'attachment_0' to 'data'
// so Call /extract API can find it via inputDataFieldName: data
const binary = $input.first().binary;
const key = Object.keys(binary).find(k => k.startsWith('attachment')) || Object.keys(binary)[0];
if (!key) throw new Error('No binary attachment found in Gmail item');
const newBinary = { data: binary[key] };
return [{ json: $input.first().json, binary: newBinary }];

